<script>
 import {onMount} from 'svelte';
 import {Check,AlertCircle,Upload,Download,ArrowRight,BookOpen} from 'lucide-svelte';
 import {inspectStory} from '../story-import.js';
 let {project=$bindable(),characters=[],locations=[],assets=[],onopen,onadd,onpage}=$props();
 let open=$state(false),sourceOpen=$state(false);
 let gaps=$derived(inspectStory({characters:characters.map(c=>({...c,image:c.image||assets.find(a=>a.type==='character'&&a.ownerId===c.id&&a.approved)?.url})),locations:locations.map(l=>({...l,image:assets.find(a=>a.type==='location'&&a.ownerId===l.id&&a.approved)?.url})),scenes:project.scenes,themes:project.themes||[]}));
 let sourceAsset=$derived(assets.find(a=>a.id===project.sourceDocument?.sourceAssetId));
 onMount(()=>{project.storyPlan||={premise:'',beginning:'',conflict:'',climax:'',resolution:''};});
 function downloadBible(){const text=['# '+project.title,project.description||'','## Story arc',...Object.entries(project.storyPlan||{}).map(([k,v])=>'### '+k+'\n'+v),'## Characters',...characters.map(c=>'### '+c.name+'\n'+c.description+'\nAppearance: '+(c.appearance||'Not specified')+'\nPersonality: '+(c.personality||'Not specified')+'\nClothing: '+(c.clothing||'Not specified')),'## Locations',...locations.map(l=>'### '+l.name+'\n'+l.description),'## Themes',...(project.themes||[]).map(t=>'### '+t.name+'\n'+t.description),'## Story',...project.scenes.map((s,i)=>'### '+(i+1)+'. '+s.title+'\n'+s.text+'\n\nActions: '+(s.actions||'Not specified')+'\nEmotions: '+(s.emotions||'Not specified')+'\nDialogue: '+(s.dialogue||'Not specified')+'\nNext: '+s.choices.map(c=>c.label+' → scene '+c.target).join('; ')),'## Details to review',...gaps.map(g=>'- '+g.detail+': '+g.label)].join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));const a=document.createElement('a');a.href=url;a.download=project.title.replace(/[^a-z0-9]+/gi,'-')+'-story-bible.md';a.click();URL.revokeObjectURL(url);}
</script>
<section class="story-readiness"><div class="readiness-heading"><button class="readiness-toggle" aria-expanded={open} onclick={()=>open=!open}><BookOpen size={17}/><span><strong>Story production checklist</strong><small>{gaps.length} details to review · source, story arc, references and scenes</small></span><span>{open?'Hide':'Review'}</span></button><button class="button secondary" onclick={downloadBible}><Download size={14}/>Export story bible</button></div>
 {#if open}<div class="readiness-content"><p>These are concrete completeness checks, not a score of storytelling quality. Drafts can be saved at any stage.</p><div class="story-plan-grid">{#each [['premise','Premise'],['beginning','Beginning'],['conflict','Central conflict'],['climax','Climax'],['resolution','Resolution and outcomes']] as [key,label]}<label class="director-field">{label}<textarea value={project.storyPlan?.[key]||''} oninput={e=>project.storyPlan={...project.storyPlan,[key]:e.currentTarget.value}} placeholder={'Define the '+label.toLowerCase()+'…'}></textarea></label>{/each}</div>
 <div class="readiness-actions"><button class="text-button" onclick={()=>onadd('character')}>Create / Import character</button><button class="text-button" onclick={()=>onadd('location')}>Create / Import location</button><button class="text-button" onclick={()=>onadd('scene')}>Create / Import scene</button><button class="text-button" onclick={()=>onadd('theme')}>Create / Import theme</button></div>
 <div class="readiness-gaps">{#each gaps as g}<button class="import-gap" onclick={()=>g.type==='scene'?onopen(g.id):onpage(g.type==='character'?'characters':g.type==='location'?'locations':'themes')}><AlertCircle size={15}/><span><strong>{g.label}</strong><small>{g.detail}</small></span><ArrowRight size={14}/></button>{:else}<p><Check size={17}/>All checked details are present.</p>{/each}</div>
 {#if project.sourceDocument}<section class="source-summary"><h3>Original manuscript</h3><p>{project.sourceDocument.originalName||project.sourceDocument.name} · {project.sourceDocument.pageCount} pages</p>{#if sourceAsset}<a class="button secondary" href={sourceAsset.url} download={project.sourceDocument.originalName||'original-story.pdf'}><Download size={14}/>Download original PDF</a>{:else}<p>The original PDF is stored on the device where it was imported. Extracted text remains in this project.</p>{/if}<button class="text-button" onclick={()=>sourceOpen=!sourceOpen}>{sourceOpen?'Hide':'Read'} preserved source text</button>{#if sourceOpen}{#each project.sourceDocument.pages||[] as p}<details><summary>Page {p.number}</summary><pre class="source-page">{p.text||'No selectable text found; review the original page.'}</pre></details>{/each}{/if}</section>{/if}
 </div>{/if}
</section>
